{
  "arguments": [
    {
      "claim": "Article 8(2)(e)(vi) of the Rome Statute criminalises rape and sexual slavery in non‑international armed conflicts irrespective of the victim’s status, so members of an armed group can be victims of these war crimes.",
      "reasoning": "The provision lists the prohibited acts (rape, sexual slavery, etc.) without qualifying the victim as a civilian; the crime is defined by the act itself. In a NIAC, the Rome Statute’s war‑crime list applies to any person against whom the act is committed, provided the conflict falls within the scope of Art 8(2)(e). Therefore, the fact that the victims are members of the same armed group does not preclude liability.",
      "citations": [
        {
          "type": "treaty",
          "instrument": "rome_statute",
          "article": "8",
          "quoted_text": "Committing rape, sexual slavery, enforced prostitution, forced pregnancy, as defined in article 7, paragraph 2 (f), enforced sterilization, or any other form of sexual violence also constituting a grave breach of the Geneva Conventions"
        }
      ]
    },
    {
      "claim": "Under Article 8(2)(c) of the Rome Statute, persons taking no active part in hostilities—including members of armed forces who have laid down their arms or are hors de combat—are protected persons, and sexual violence against them constitutes a war crime.",
      "reasoning": "Art 8(2)(c) expressly states that serious violations of Common Article 3, such as rape, are prohibited when committed against \"persons taking no active part in the hostilities, including members of armed forces who have laid down their arms and those placed hors de combat.\" Child soldiers who are subjected to sexual violence are not actively participating in hostilities at the moment of the offence and thus fall within this protected category, satisfying the victim element of the war‑crime provision.",
      "citations": [
        {
          "type": "treaty",
          "instrument": "rome_statute",
          "article": "8",
          "quoted_text": "In the case of an armed conflict not of an international character, serious violations of article 3 common to the four Geneva Conventions ... any of the following acts committed against persons taking no active part in the hostilities, including members of armed forces who have laid down their arms and those placed hors de combat"
        }
      ]
    },
    {
      "claim": "Article 8(2)(f) confirms that the provisions of Article 8(2)(e) – including the sexual‑violence offences – apply to the type of conflict present in Ituri, i.e., a protracted non‑international armed conflict between governmental authorities and an organized armed group.",
      "reasoning": "The text of Art 8(2)(f) limits the application of Art 8(2)(e) to NIACs that occur on the territory of a State between governmental forces and organized armed groups (or between such groups). The facts describe exactly such a conflict involving the UPC/FPLC, satisfying the jurisdictional prerequisite and allowing the war‑crime provisions to be invoked against intra‑group sexual violence.",
      "citations": [
        {
          "type": "treaty",
          "instrument": "rome_statute",
          "article": "8(2)(f)",
          "quoted_text": "Paragraph 2 (e) applies to armed conflicts not of an international character ... It applies to armed conflicts that take place in the territory of a State when there is protracted armed conflict between governmental authorities and organized armed groups or between such groups."
        }
      ]
    },
    {
      "claim": "The defence’s contention that protection against war crimes attaches only after a combatant ceases to be a member of the armed group is inconsistent with the explicit wording of Article 8(2)(c).",
      "reasoning": "Art 8(2)(c) does not require a combatant to have formally left the armed group; it merely requires that the person be \"taking no active part in the hostilities\" or be \"hors de combat.\" The statute therefore extends protection to members who are temporarily out of combat – for example, when they are detained, wounded, or otherwise unable to fight – and to child soldiers who are compelled to serve. Consequently, the victims in this case are covered by the protected‑person regime, and the war‑crime elements are satisfied.",
      "citations": [
        {
          "type": "treaty",
          "instrument": "rome_statute",
          "article": "8",
          "quoted_text": "including members of armed forces who have laid down their arms and those placed hors de combat"
        }
      ]
    },
    {
      "claim": "Even if the victims were still formally members of the armed group, customary international humanitarian law, as reflected in the Rome Statute’s incorporation of the Geneva Conventions, prohibits sexual violence against any person who is not actively participating in hostilities, regardless of affiliation.",
      "reasoning": "While the Rome Statute does not expressly repeat the customary rule, its adoption of the Geneva Conventions’ protections (see Art 8(2)(c) and the reference to \"grave breach of the Geneva Conventions\") demonstrates that the prohibition applies to all persons who are not taking an active part, including members of the opposing armed group. This reinforces the argument that intra‑group rape and sexual slavery are war crimes under the Statute.",
      "citations": [
        {
          "type": "treaty",
          "instrument": "rome_statute",
          "article": "8",
          "quoted_text": "any other form of sexual violence also constituting a grave breach of the Geneva Conventions"
        }
      ]
    }
  ]
}

