{
  "arguments": [
    {
      "claim": "Article 8(2)(e)(vi) criminalises rape and sexual slavery in a non‑international armed conflict regardless of the victim’s affiliation, so members of the UPC/FPLC can be victims.",
      "reasoning": "The provision enumerates the prohibited acts (rape, sexual slavery, etc.) without qualifying the victim as a civilian or non‑combatant. Consequently the crime is defined solely by the act itself, and any person against whom the act is committed in the context of a NIAC falls within the scope of the war‑crime element. The child soldiers of the UPC/FPLC were subjected to rape and sexual slavery while the conflict met the NIAC criteria, satisfying the victim element of Art 8(2)(e)(vi).",
      "citations": [
        {
          "type": "treaty",
          "instrument": "rome_statute",
          "article": "8",
          "quoted_text": "Committing rape, sexual slavery, enforced prostitution, forced pregnancy, as defined in article 7, paragraph 2 (f), enforced sterilization, or any other form of sexual violence also constituting a grave breach of the Geneva Conventions"
        }
      ]
    },
    {
      "claim": "Article 8(2)(c) defines the protected‑person regime in non‑international armed conflicts and covers persons who have laid down arms or are hors de combat, which includes child soldiers at the moment of the offence, thereby satisfying the victim element for the charge under 8(2)(e)(vi).",
      "reasoning": "While the charge is anchored in Art 8(2)(e)(vi), the victim element is still drawn from the protected‑person definition in Art 8(2)(c). That article expressly protects \"persons taking no active part in the hostilities, including members of armed forces who have laid down their arms and those placed hors de combat.\" The alleged victims were child soldiers who were not actively participating in hostilities at the time of the sexual violence (e.g., detained, wounded, or otherwise unable to fight). Therefore they fall within the protected‑person category, meeting the victim requirement for the war‑crime charge.",
      "citations": [
        {
          "type": "treaty",
          "instrument": "rome_statute",
          "article": "8(2)(c)",
          "quoted_text": "any of the following acts committed against persons taking no active part in the hostilities, including members of armed forces who have laid down their arms and those placed hors de combat"
        }
      ]
    },
    {
      "claim": "Article 8(2)(f) confirms that the conduct occurred within the scope of a non‑international armed conflict between a State and an organized armed group, giving the Court jurisdiction over the war‑crime counts.",
      "reasoning": "Art 8(2)(f) limits the application of Art 8(2)(e) to NIACs that take place on the territory of a State when there is a protracted armed conflict between governmental authorities and organized armed groups or between such groups. The Ituri situation involved the UPC/FPLC, an organized armed group, fighting in the DRC’s territory against government forces, satisfying the statutory description and thus establishing jurisdiction.",
      "citations": [
        {
          "type": "treaty",
          "instrument": "rome_statute",
          "article": "8(2)(f)",
          "quoted_text": "Paragraph 2 (e) applies to armed conflicts not of an international character and thus does not apply to situations of internal disturbances and tensions, such as riots, isolated and sporadic acts of violence or other acts of a similar nature. It applies to armed conflicts that take place in the territory of a State when there is protracted armed conflict between governmental authorities and organized armed groups or between such groups."
        }
      ]
    }
  ]
}

